// TestWriteCache_RechmodsExistingFile guards against a stale cache entry
// written under an older, laxer-permission build (e.g. pre-upgrade 0o644)
// staying world-readable forever: os.WriteFile only applies its perm
// argument when creating a file, so an existing file's mode has to be
// corrected explicitly on every write.
func TestWriteCache_RechmodsExistingFile(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX permission bits don't map cleanly to Windows ACLs")
	}
	t.Parallel()

	dir := t.TempDir()
	c := &Client{cacheDir: dir}

	cacheFile := filepath.Join(dir, c.cacheKey("/v1/mutations", nil)+".json")
	if err := os.WriteFile(cacheFile, []byte(`{"stale": true}`), 0o644); err != nil {
		t.Fatalf("seed stale cache file: %v", err)
	}

	c.writeCache("/v1/mutations", nil, json.RawMessage(`{"fresh": true}`))

	info, err := os.Stat(cacheFile)
	if err != nil {
		t.Fatalf("stat cache file: %v", err)
	}
	if got := info.Mode().Perm(); got != 0o600 {
		t.Fatalf("cache file mode = %o, want 0600 (existing file must be re-chmodded on rewrite)", got)
	}
}

// TestReadCache_RechmodsFreshLegacyFile guards against the read-side gap in
// the same class of bug TestWriteCache_RechmodsExistingFile covers: a cache
// entry that is still inside the 5-minute TTL is returned straight from
// readCache without ever reaching writeCache's chmod, so a fresh pre-upgrade
// 0o644 entry would otherwise stay world-readable for up to 5 minutes after
// an upgrade.
func TestReadCache_RechmodsFreshLegacyFile(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX permission bits don't map cleanly to Windows ACLs")
	}
	t.Parallel()

	dir := t.TempDir()
	c := &Client{cacheDir: dir}

	cacheFile := filepath.Join(dir, c.cacheKey("/v1/mutations", nil)+".json")
	if err := os.WriteFile(cacheFile, []byte(`{"fresh": true}`), 0o644); err != nil {
		t.Fatalf("seed fresh legacy cache file: %v", err)
	}

	if _, ok := c.readCache("/v1/mutations", nil); !ok {
		t.Fatalf("readCache: expected a hit on a fresh file")
	}

	info, err := os.Stat(cacheFile)
	if err != nil {
		t.Fatalf("stat cache file: %v", err)
	}
	if got := info.Mode().Perm(); got != 0o600 {
		t.Fatalf("cache file mode = %o, want 0600 (a fresh legacy 0644 entry must be re-chmodded on a cache-hit read, not only on rewrite)", got)
	}
}

// TestReadCache_RechmodsExpiredLegacyFile guards against the gap Greptile
// found in the fresh-file fix above: the TTL check used to return a cache
// miss before the chmod ever ran, so a legacy 0o644 entry that expired
// before its key was successfully rewritten (a failed live fetch, an API
// outage) stayed world-readable indefinitely.
func TestReadCache_RechmodsExpiredLegacyFile(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX permission bits don't map cleanly to Windows ACLs")
	}
	t.Parallel()

	dir := t.TempDir()
	c := &Client{cacheDir: dir}

	cacheFile := filepath.Join(dir, c.cacheKey("/v1/mutations", nil)+".json")
	if err := os.WriteFile(cacheFile, []byte(`{"stale": true}`), 0o644); err != nil {
		t.Fatalf("seed expired legacy cache file: %v", err)
	}
	expired := time.Now().Add(-10 * time.Minute)
	if err := os.Chtimes(cacheFile, expired, expired); err != nil {
		t.Fatalf("backdate cache file mtime: %v", err)
	}

	if _, ok := c.readCache("/v1/mutations", nil); ok {
		t.Fatalf("readCache: expected a miss on an expired file")
	}

	info, err := os.Stat(cacheFile)
	if err != nil {
		t.Fatalf("stat cache file: %v", err)
	}
	if got := info.Mode().Perm(); got != 0o600 {
		t.Fatalf("cache file mode = %o, want 0600 (an expired legacy 0644 entry must be re-chmodded even on a cache-miss read)", got)
	}
}

func TestTruncateBody(t *testing.T) {
	t.Parallel()

	const maxBytes = 4096

	cases := []struct {
		name        string
		input       []byte
		wantLen     int
		wantHasTail bool
	}{
		{"empty", nil, 0, false},
		{"under cap", []byte("hello"), 5, false},
		{"at cap", bytes.Repeat([]byte("a"), maxBytes), maxBytes, false},
		{"one over cap", bytes.Repeat([]byte("a"), maxBytes+1), maxBytes + 3, true},
		{"huge body", bytes.Repeat([]byte("a"), maxBytes*8), maxBytes + 3, true},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got := truncateBody(tc.input)
			if len(got) != tc.wantLen {
				t.Fatalf("len = %d, want %d", len(got), tc.wantLen)
			}
			if tc.wantHasTail && !strings.HasSuffix(got, "...") {
				t.Fatalf("want trailing %q", "...")
			}
			if !tc.wantHasTail && strings.HasSuffix(got, "...") {
				t.Fatalf("unexpected trailing %q in %q", "...", got)
			}
		})
	}
}

func TestTruncateBody_UTF8RuneAtBoundary(t *testing.T) {
	t.Parallel()

	// '€' is 3 bytes (0xE2 0x82 0xAC). Place it so the slice at byte 4096 cuts
	// mid-rune; strings.ToValidUTF8 should drop the partial rune cleanly rather
	// than emit U+FFFD or invalid UTF-8.
	prefix := strings.Repeat("a", 4094)
	body := []byte(prefix + "€" + strings.Repeat("b", 100))
	got := truncateBody(body)

	if !utf8.ValidString(got) {
		t.Fatalf("output is not valid UTF-8")
	}
	if strings.ContainsRune(got, utf8.RuneError) {
		t.Fatalf("output contains replacement rune U+FFFD")
	}
	if !strings.HasSuffix(got, "...") {
		t.Fatalf("want trailing %q", "...")
	}
	// Partial rune must be dropped, not replaced: 4094 valid bytes + "...".
	if want := 4094 + 3; len(got) != want {
		t.Fatalf("len = %d, want %d (partial rune should be dropped, not replaced)", len(got), want)
	}
}
